// Wide copy path: non-overlapping (rep0 >= curLen) and curLen >= 16
	CMPL	DX, 128(SP)
	JHI	copy_no_wrap_byte
	CMPL	DX, $16
	JCS	copy_no_wrap_byte

// 16-byte MOVOU copy loop
	SUBQ	DX, R14
	MOVQ	DX, BX
	ANDQ	$-16, BX
