	MOVOU	(DI), X0
	MOVOU	X0, (R14)
	ADDQ	$16, DI
	ADDQ	$16, R14
	SUBQ	$16, BX
	JNE	copy_wide_loop
	ANDL	$15, DX
	JEQ	copy_wide_done
