	DECL	CX
	JNE	spec_loop

	MOVQ	64(SP), R11
	SUBL	R9, BX
	SUBL	$-3328, BX
	SUBQ	R11, BX
	SHRL	$1, BX

	JMP	decode_dist_end

// ============================================================
// COPY MATCH CROSS
// ============================================================
copy_match_cross:
// t0 = srcPos, pbPos(r1) = remaining to dicBufSize end, cnt_R = total len
	MOVQ	DI, SI
	MOVQ	R12, DI
	MOVQ	56(SP), CX
	NEGQ	DX
copy_cross_loop:
	MOVBLZX	(DI)(SI*1), BX
	INCQ	SI
	MOVB	BX, (R14)(DX*1)
	INCQ	DX
	CMPQ	SI, CX
	JNE	copy_cross_loop

	MOVBLZX	(DI), BX
	SUBQ	DX, DI
	JMP	copy_common

// ============================================================
// FIN
// ============================================================
fin_dicPos_LIMIT:
	MOVL	BX, 112(SP)
	JMP	fin_OK

fin_ERROR_MATCH_DIST:
// fin_ERROR_MATCH_DIST
	ADDL	$512, R12
	MOVL	R12, 112(SP)

	MOVL	BX, 128(SP)
	MOVL	SI, 132(SP)
	MOVL	CX, 136(SP)
	MOVL	DX, 140(SP)

	CMPL	R8, $38
	MOVL	$14, R8
	MOVL	$20, DI
	CMOVLCC	DI, R8

	MOVL	$1, BX
	JMP	fin

end_of_payload:
	INCL	BX
	JNE	fin_ERROR_MATCH_DIST

	MOVL	$274, 112(SP)
	SUBL	$24, R8

fin_OK:
	XORL	BX, BX

fin:
	CMPL	AX, $16777216
	JCC	norm_42
	SHLL	$8, BP
	SHLL	$8, AX
	MOVBLZX	(R15), DI
	ORL	DI, BP
	INCQ	R15
norm_42:

// Store results back to struct
	MOVQ	48(SP), CX

	SUBQ	72(SP), R14
	MOVQ	R14, cLzmaDec_dicPos(CX)
	MOVQ	R15, cLzmaDec_buf(CX)
	MOVL	AX, cLzmaDec_rng(CX)
	MOVL	BP, cLzmaDec_code(CX)
	SHRL	$1, R8
	MOVL	R8, cLzmaDec_state(CX)
	MOVL	R13, cLzmaDec_processedPos(CX)

	MOVL	112(SP), DI
	MOVL	DI, cLzmaDec_remainLen(CX)
	MOVL	128(SP), DI
	MOVL	DI, cLzmaDec_rep0(CX)
	MOVL	132(SP), DI
	MOVL	DI, cLzmaDec_rep1(CX)
	MOVL	136(SP), DI
	MOVL	DI, cLzmaDec_rep2(CX)
	MOVL	140(SP), DI
	MOVL	DI, cLzmaDec_rep3(CX)

// Return value
	MOVL	BX, DI

// Restore callee-saved registers
	MOVQ	(SP), BX
	MOVQ	8(SP), BP
	MOVQ	16(SP), R12
	MOVQ	24(SP), R13
	MOVQ	32(SP), R14
	MOVQ	40(SP), R15

	ADDQ	$152, SP

	MOVL	DI, ret+24(FP)
	RET

